/*
 * Runtime support for the C code generated by tools/port/asm2c.py from the
 * game's hand-written ARM/Thumb routines (m4a sound engine core, arm_funcs.s).
 *
 * Memory model of the port (32-bit on every target):
 *   0x04000000..0x040003FF  GBA I/O registers  -> gHostIo[0x400]
 *   0x03000000..0x03007FFF  IWRAM              -> gHostIwram[0x8000]
 *   0x02000000..0x0203FFFF  EWRAM              -> gHostEwram[0x40000]
 *   everything else          a real host pointer, used as is.
 * Constants the assembly builds from literal pools are mapped at load time
 * (see const_addr() in asm2c.py); computed addresses are mapped on access.
 */
#ifndef PORT_ASM_RT_H
#define PORT_ASM_RT_H

#include <stdint.h>
#include <stdlib.h>

#include "gba/types.h"
#include "gba/m4a_internal.h"

extern unsigned char gHostIo[0x400];
extern unsigned char gHostIwram[0x8000];
extern unsigned char gHostEwram[0x40000];

static inline unsigned char *AsmRt_MapSlow(u32 a)
{
    u32 o = a - 0x04000000u;
    if (o < 0x400u)
        return gHostIo + o;
    o = a - 0x03000000u;
    if (o < 0x8000u)
        return gHostIwram + o;
    o = a - 0x02000000u;
    if (o < 0x40000u)
        return gHostEwram + o;
    return (unsigned char *)(uintptr_t)a;
}

static inline unsigned char *AsmRt_Map(u32 a)
{
    /* One range check on the fast path: GBA RAM/IO constants are all in
     * 0x02000000..0x040003FF, real host pointers never are (on the Vita the
     * executable lives at 0x81000000, on 32-bit Linux at 0x08000000 or above). */
    if (__builtin_expect(a - 0x02000000u < 0x02000400u, 0))
        return AsmRt_MapSlow(a);
    return (unsigned char *)(uintptr_t)a;
}

#define P(a) ((void *)AsmRt_Map(a))
#define LD8(a) (*(u8 *)AsmRt_Map(a))
#define LD16(a) (*(u16 *)AsmRt_Map(a))
#define LD32(a) (*(u32 *)AsmRt_Map(a))
#define ST8(a, x) (*(u8 *)AsmRt_Map(a) = (u8)(x))
#define ST16(a, x) (*(u16 *)AsmRt_Map(a) = (u16)(x))
#define ST32(a, x) (*(u32 *)AsmRt_Map(a) = (u32)(x))

/* Tagged registers (asm2c --tag): the top two bits of the PCM mixer's output
 * pointer are a loop counter on the GBA.  They live in a separate variable;
 * with ASM_RT_CHECKS defined every other use of the register verifies that the
 * tag is clear, as it always is in the original code at those points. */
#ifdef ASM_RT_CHECKS
#define ASM_TAG_CHECK(t) do { if ((t) != 0) abort(); } while (0)
#else
#define ASM_TAG_CHECK(t) ((void)0)
#endif

/* Register-specified shifts (amount = Rs & 0xff); *c is the carry flag. */
static inline u32 SHIFT_LSL(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    if (a < 32) { *c = (x >> (32 - a)) & 1; return x << a; }
    *c = (a == 32) ? (x & 1) : 0;
    return 0;
}

static inline u32 SHIFT_LSR(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    if (a < 32) { *c = (x >> (a - 1)) & 1; return x >> a; }
    *c = (a == 32) ? (x >> 31) : 0;
    return 0;
}

static inline u32 SHIFT_ASR(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    if (a < 32) { *c = ((u32)((s32)x >> (a - 1))) & 1; return (u32)((s32)x >> a); }
    *c = x >> 31;
    return (u32)((s32)x >> 31);
}

static inline u32 SHIFT_ROR(u32 x, u32 a, u32 *c)
{
    if (a == 0) return x;
    a &= 31;
    if (a == 0) { *c = x >> 31; return x; }
    *c = (x >> (a - 1)) & 1;
    return (x >> a) | (x << (32 - a));
}

#endif /* PORT_ASM_RT_H */
